from django import forms
from .models import Article, Comment

class ArticleForm(forms.ModelForm):
    # 可以在这里添加额外的字段，或者重写模型字段
    # 比如添加一个确认字段，或者修改widget

    class Meta:
        model = Article
        fields = ['title', 'summary', 'content', 'category', 'tags', 'is_published']
        # 或者 fields = '__all__' （不推荐，可能暴露不该有的字段）
        # 或者 exclude = ['author', 'views', 'pub_date', 'update_time']

        # 自定义标签
        labels = {
            'title': '文章标题',
            'content': '文章内容',
            'is_published': '立即发布',
        }

        # 自定义widget
        widgets = {
            'title': forms.TextInput(attrs={'class': 'form-control'}),
            'summary': forms.TextInput(attrs={'class': 'form-control'}),
            'content': forms.Textarea(attrs={'class': 'form-control', 'rows': 15}),
            'category': forms.Select(attrs={'class': 'form-control'}),
            'tags': forms.CheckboxSelectMultiple(),  # 多选复选框
        }

        # 自定义帮助文本
        help_texts = {
            'title': '标题不超过200字',
            'tags': '按住Ctrl可多选',
        }

# 视图中使用
def article_create(request):
    if request.method == 'POST':
        form = ArticleForm(request.POST)
        if form.is_valid():
            # save()返回保存的对象，commit=False表示先不保存到数据库
            article = form.save(commit=False)
            article.author = request.user  # 设置当前登录用户为作者
            article.save()  # 保存主对象
            form.save_m2m()  # 多对多字段需要单独保存（用了commit=False的话）
            return redirect('blog:detail', article_id=article.id)
    else:
        form = ArticleForm()

    return render(request, 'blog/article_form.html', {'form': form})

# 编辑文章
def article_edit(request, article_id):
    article = get_object_or_404(Article, id=article_id)

    if request.method == 'POST':
        # 传入instance表示更新已有对象
        form = ArticleForm(request.POST, instance=article)
        if form.is_valid():
            form.save()  # 直接保存
            return redirect('blog:detail', article_id=article.id)
    else:
        # 编辑时传入instance，表单会填充现有数据
        form = ArticleForm(instance=article)

    return render(request, 'blog/article_form.html', {'form': form})

