Nginx作为反向代理，处理静态文件、转发动态请求给Gunicorn、SSL等。

创建Nginx配置文件 /etc/nginx/sites-available/myblog：

server {
    listen 80;
    server_name yourdomain.com www.yourdomain.com;

    # 日志
    access_log /var/log/nginx/myblog_access.log;
    error_log /var/log/nginx/myblog_error.log;

    # 静态文件
    location /static/ {
        alias /home/deploy/myblog/staticfiles/;
        expires 30d;
        add_header Cache-Control "public, immutable";
    }

    # 媒体文件
    location /media/ {
        alias /home/deploy/myblog/media/;
        expires 30d;
    }

    # 动态请求转发给Gunicorn
    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # 超时时间
        proxy_connect_timeout 30s;
        proxy_read_timeout 30s;
        proxy_send_timeout 30s;

        # 上传文件大小限制
        client_max_body_size 50M;
    }
}

启用站点：

sudo ln -s /etc/nginx/sites-available/myblog /etc/nginx/sites-enabled/
# 删除默认站点（可选）
sudo rm /etc/nginx/sites-enabled/default

# 测试配置
sudo nginx -t

# 重载Nginx
sudo systemctl reload nginx

